    "question": "Which condition guarantees that an undirected graph has an Eulerian circuit?",
    "options": {
      "A": "The graph is connected and every vertex has even degree",
      "B": "The graph is connected and exactly two vertices have odd degree",
      "C": "The graph is acyclic and has at least one vertex of degree 1",
      "D": "The graph is planar and has a Hamiltonian path"
    },
    "correct_answer": "A",
    "explanation": "Euler's theorem states that a connected undirected graph possesses an Eulerian circuit iff every vertex has even degree.",
    "difficulty": "Medium"
  },
